1315  sc_pkcs15_pubkey_from_spki_fields(struct sc_context *ctx, struct sc_pkcs15_pubkey **outpubkey,
  1316                  unsigned char *buf, size_t buflen, int depth)
  1317  {
  1318
  1319          struct sc_pkcs15_pubkey *pubkey = NULL;
  1320          struct sc_pkcs15_der pk = { NULL, 0 };
  1321          struct sc_algorithm_id pk_alg;
  1322          struct sc_asn1_entry asn1_pkinfo[C_ASN1_PKINFO_ATTR_SIZE];
  1323          unsigned char *tmp_buf = NULL;
  1324          int r;
  1325
  1326          sc_log(ctx,
  1327                 "sc_pkcs15_pubkey_from_spki_fields() called: %p:%"SC_FORMAT_LEN_SIZE_T"u\n%s",
  1328                 buf, buflen, sc_dump_hex(buf, buflen));
  1329
  1330          tmp_buf = malloc(buflen);
  1331          if (!tmp_buf) {
  1332                  r = SC_ERROR_OUT_OF_MEMORY;
  1333                  LOG_TEST_GOTO_ERR(ctx, r, "");
  1334          }
  1335          memcpy(tmp_buf, buf, buflen);
  1336
  1337          if ((*tmp_buf & SC_ASN1_TAG_CONTEXT))
  1338                  *tmp_buf = SC_ASN1_TAG_CONSTRUCTED | SC_ASN1_TAG_SEQUENCE;
  1339
  1340          memset(&pk_alg, 0, sizeof(pk_alg));
  1341          pubkey = calloc(1, sizeof(sc_pkcs15_pubkey_t));
  1342          if (pubkey == NULL) {
  1343                  r = SC_ERROR_OUT_OF_MEMORY;
  1344                  LOG_TEST_GOTO_ERR(ctx, r, "");
  1345          }
  1346
  1347          sc_copy_asn1_entry(c_asn1_pkinfo, asn1_pkinfo);
  1348
  1349          sc_format_asn1_entry(asn1_pkinfo + 0, &pk_alg, NULL, 0);
  1350          sc_format_asn1_entry(asn1_pkinfo + 1, &pk.value, &pk.len, 0);
  1351
  1352          r = sc_asn1_decode(ctx, asn1_pkinfo, tmp_buf, buflen, NULL, NULL);
  1353          if (r != SC_SUCCESS) {
  1354                  sc_asn1_clear_algorithm_id(&pk_alg);
  1355                  LOG_TEST_GOTO_ERR(ctx, r, "ASN.1 parsing of subjectPubkeyInfo failed");
  1356          }
  1357
  1358          pubkey->alg_id = calloc(1, sizeof(struct sc_algorithm_id));
  1359          if (pubkey->alg_id == NULL) {
  1360                  r = SC_ERROR_OUT_OF_MEMORY;
  1361                  LOG_TEST_GOTO_ERR(ctx, r, "");
  1362          }
  1363
  1364          memcpy(pubkey->alg_id, &pk_alg, sizeof(struct sc_algorithm_id));
  1365          pubkey->algorithm = pk_alg.algorithm;
  1366          pk_alg.params = NULL;
  1367          sc_log(ctx, "DEE pk_alg.algorithm=%d", pk_alg.algorithm);
  1368
  1369          pk.len = (pk.len + 7)/8;        /* convert number of bits to bytes */
  1370
  1371          if (pk_alg.algorithm == SC_ALGORITHM_EC)   {
  1372                  /* EC public key is not encapsulated into BIT STRING -- it's a BIT STRING */
  1373                  /*
  1374                   * sc_pkcs15_fix_ec_parameters below will set field_length from curve.
  1375                   * if no alg_id->params, assume field_length is multiple of 8
  1376                   */
  1377                  pubkey->u.ec.params.field_length = (pk.len - 1) / 2 * 8;
  1378
  1379                  if (pubkey->alg_id->params) {
  1380                          struct sc_ec_parameters *ecp = (struct sc_ec_parameters *)pubkey->alg_id->params;
  1381
  1382                          pubkey->u.ec.params.der.value = malloc(ecp->der.len);
  1383                          if (pubkey->u.ec.params.der.value == NULL) {
  1384                                  r = SC_ERROR_OUT_OF_MEMORY;
  1385                                  LOG_TEST_GOTO_ERR(ctx, r, "");
  1386                          }
  1387
  1388                          memcpy(pubkey->u.ec.params.der.value, ecp->der.value, ecp->der.len);
  1389                          pubkey->u.ec.params.der.len = ecp->der.len;
  1390                          r = sc_pkcs15_fix_ec_parameters(ctx, &pubkey->u.ec.params);
  1391                          LOG_TEST_GOTO_ERR(ctx, r, "failed to fix EC parameters");
  1392                  }
  1393
  1394                  pubkey->u.ec.ecpointQ.value = malloc(pk.len);
  1395                  if (pubkey->u.ec.ecpointQ.value == NULL) {
  1396                          r = SC_ERROR_OUT_OF_MEMORY;
  1397                          LOG_TEST_GOTO_ERR(ctx, r, "failed to malloc() memory");
  1398                  }
  1399                  memcpy(pubkey->u.ec.ecpointQ.value, pk.value, pk.len);
  1400                  pubkey->u.ec.ecpointQ.len = pk.len;
  1401          } else if (pk_alg.algorithm == SC_ALGORITHM_EDDSA ||
  1402                     pk_alg.algorithm == SC_ALGORITHM_XEDDSA) {
  1403                  /* EDDSA/XEDDSA public key is not encapsulated into BIT STRING -- it's a BIT STRING */
  1404                  pubkey->u.eddsa.pubkey.value = malloc(pk.len);
  1405                  memcpy(pubkey->u.eddsa.pubkey.value, pk.value, pk.len);
  1406                  pubkey->u.eddsa.pubkey.len = pk.len;
  1407          } else {
  1408                  /* Public key is expected to be encapsulated into BIT STRING */
  1409                  r = sc_pkcs15_decode_pubkey(ctx, pubkey, pk.value, pk.len);
  1410                  LOG_TEST_GOTO_ERR(ctx, r, "ASN.1 parsing of subjectPubkeyInfo failed");
  1411          }
  1412
  1413          *outpubkey = pubkey;
  1414          pubkey = NULL;
  1415
  1416  err:
  1417          if (pubkey)
  1418                  sc_pkcs15_free_pubkey(pubkey);
  1419          if (pk.value)
  1420                  free(pk.value);
  1421          if (tmp_buf)
  1422                  free(tmp_buf);
  1423
  1424          LOG_FUNC_RETURN(ctx, r);
  1425  }
