  1429  sc_pkcs15_pubkey_from_spki_sequence(struct sc_context *ctx, const unsigned char *buf, size_t buflen,
  1430                  struct sc_pkcs15_pubkey ** outpubkey)
  1431  {
  1432          struct sc_pkcs15_pubkey * pubkey = NULL;
  1433          struct sc_asn1_entry asn1_spki[] = {
  1434                          { "subjectPublicKeyInfo", SC_ASN1_CALLBACK, SC_ASN1_TAG_SEQUENCE | SC_ASN1_CONS, 0, sc_pkcs15_pubkey_from_spki_fields, &pubkey},
  1435                          { NULL, 0, 0, 0, NULL, NULL } };
  1436          int r;
  1437
  1438          LOG_FUNC_CALLED(ctx);
  1439
  1440          r = sc_asn1_decode(ctx, asn1_spki, buf, buflen, NULL, NULL);
  1441          LOG_TEST_RET(ctx, r, "ASN.1 cannot parse subjectPublicKeyInfo");
  1442
  1443          if(outpubkey) {
  1444                  free(*outpubkey);
  1445                  *outpubkey = pubkey;
  1446          } else
  1447                  free(pubkey);
  1448
  1449          LOG_FUNC_RETURN(ctx, r);
  1450  }
